use itertools::Itertools;
use std::collections::HashMap;

pub fn solve(input: &str) -> Option<HashMap<char, u8>> {
    let (lhs, rhs) = input.split_once("==")?;

    let mut coefficients: HashMap<char, i128> = HashMap::new();
    let mut leading: Vec<char> = Vec::new();

    let mut register_word = |word: &str, sign: i128| {
        let word = word.trim();
        if word.len() > 1 {
            if let Some(first) = word.chars().next() {
                if !leading.contains(&first) {
                    leading.push(first);
                }
            }
        }
        for (index, ch) in word.chars().enumerate() {
            let power = (word.len() - 1 - index) as u32;
            *coefficients.entry(ch).or_insert(0) += sign * 10_i128.pow(power);
        }
    };

    for word in lhs.split('+') {
        register_word(word, 1);
    }
    for word in rhs.split('+') {
        register_word(word, -1);
    }

    let mut letters: Vec<char> = coefficients.keys().copied().collect();
    if letters.len() > 10 {
        return None;
    }
    letters.sort_by_key(|letter| !leading.contains(letter));

    let coefficients: Vec<i128> = letters.iter().map(|letter| coefficients[letter]).collect();
    let leading_positions: Vec<usize> = letters
        .iter()
        .enumerate()
        .filter_map(|(position, letter)| leading.contains(letter).then_some(position))
        .collect();

    for permutation in (0..10).permutations(letters.len()) {
        if leading_positions.iter().any(|&position| permutation[position] == 0) {
            continue;
        }
        let total: i128 = coefficients
            .iter()
            .zip(permutation.iter())
            .map(|(&coefficient, &digit)| coefficient * digit as i128)
            .sum();
        if total == 0 {
            return Some(
                letters
                    .iter()
                    .copied()
                    .zip(permutation.iter().copied().map(u8::try_from))
                    .filter_map(|(letter, digit)| digit.ok().map(|digit| (letter, digit)))
                    .collect(),
            );
        }
    }

    None
}
